CREATE TABLE IF NOT EXISTS auth_user (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, email_verified boolean NOT NULL DEFAULT false, image text, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS auth_session (id text PRIMARY KEY, expires_at timestamp NOT NULL, token text NOT NULL UNIQUE, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now(), ip_address text, user_agent text, user_id text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS auth_session_user_idx ON auth_session(user_id);
CREATE TABLE IF NOT EXISTS auth_account (id text PRIMARY KEY, account_id text NOT NULL, provider_id text NOT NULL, user_id text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE, access_token text, refresh_token text, id_token text, access_token_expires_at timestamp, refresh_token_expires_at timestamp, scope text, password text, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now(), UNIQUE(provider_id, account_id));
CREATE TABLE IF NOT EXISTS auth_verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, expires_at timestamp NOT NULL, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS verification_identifier ON auth_verification(identifier);
CREATE TABLE IF NOT EXISTS profiles (user_id text PRIMARY KEY REFERENCES auth_user(id) ON DELETE CASCADE, level text NOT NULL DEFAULT 'Trung cấp', goal text NOT NULL DEFAULT 'Tự học tiếng Hàn', minutes integer NOT NULL DEFAULT 20 CHECK(minutes BETWEEN 5 AND 120), timezone text NOT NULL DEFAULT 'Asia/Ho_Chi_Minh');
CREATE TABLE IF NOT EXISTS drafts (user_id text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE, sentence_id text NOT NULL, text text NOT NULL, version integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,sentence_id));
CREATE TABLE IF NOT EXISTS favorites (user_id text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE, sentence_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,sentence_id));
CREATE TABLE IF NOT EXISTS submissions (id text PRIMARY KEY, user_id text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE, sentence_id text NOT NULL, translation text NOT NULL, snapshot jsonb NOT NULL, report jsonb, status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','active','completed','failed')), error text, dedup_key text NOT NULL UNIQUE, model text NOT NULL, prompt_version text NOT NULL, rubric_version text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE INDEX IF NOT EXISTS submissions_user_date ON submissions(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS vocabulary (id text PRIMARY KEY, user_id text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE, term text NOT NULL, meaning text NOT NULL, context text NOT NULL DEFAULT '', note text NOT NULL DEFAULT '', source_id text, kind text NOT NULL DEFAULT 'word', suspended boolean NOT NULL DEFAULT false, card jsonb NOT NULL, due timestamptz NOT NULL, version integer NOT NULL DEFAULT 1, algorithm text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,term,kind));
CREATE INDEX IF NOT EXISTS vocabulary_due ON vocabulary(user_id,due) WHERE NOT suspended;
CREATE TABLE IF NOT EXISTS review_logs (id text PRIMARY KEY, user_id text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE, card_id text NOT NULL REFERENCES vocabulary(id) ON DELETE CASCADE, rating integer NOT NULL CHECK(rating BETWEEN 1 AND 4), log jsonb NOT NULL, reviewed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS daily_plans (user_id text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE, day text NOT NULL, timezone text NOT NULL, tasks jsonb NOT NULL, version integer NOT NULL DEFAULT 1, completed boolean NOT NULL DEFAULT false, PRIMARY KEY(user_id,day));
CREATE TABLE IF NOT EXISTS study_days (user_id text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE, day text NOT NULL, PRIMARY KEY(user_id,day));
CREATE TABLE IF NOT EXISTS legacy_imports (legacy_id text PRIMARY KEY, user_id text NOT NULL REFERENCES auth_user(id), imported_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS recordings (id text PRIMARY KEY, user_id text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE, object_key text NOT NULL, transcript text, feedback jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS exam_attempts (id text PRIMARY KEY, user_id text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE, exam_id text NOT NULL, snapshot jsonb NOT NULL, answers jsonb NOT NULL DEFAULT '{}', started_at timestamptz NOT NULL DEFAULT now(), deadline timestamptz NOT NULL, submitted_at timestamptz, result jsonb, version integer NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS exam_attempts_user ON exam_attempts(user_id,started_at DESC);
CREATE TABLE IF NOT EXISTS tutor_chunks (id text PRIMARY KEY, content_id text NOT NULL, content_version integer NOT NULL, text text NOT NULL);
